const params = {
    "id_usuario": "16",
    "action": "architecto",
    "table_name": "architecto",
    "record_id": "16",
    "desde": "architecto",
    "hasta": "architecto",
    "modo": "architecto",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Authorization": "Bearer TOKEN_DE_MUESTRA",
    "Content-Type": "application/json",
    "Accept": "application/json",
};


fetch(url, {
